    const nextCursor = encodeCursor(nextIndex);
    text = JSON.stringify({ events: page, next_cursor: nextCursor });
  } else {
    text = JSON.stringify({ events: page });
  }

  return {
    content: [{ type: 'text', text }]
  };
}
